    faq_a_bag_examples_list: "새 가방에는 다른 것처럼 바꾸거나 지울 수 있는 예시가 들어 있어요. 집(장보기, 레시피, 이번 주 식단), 가족(작은 순간들, 생일 파티 체크리스트, 학원과 활동), 아이디어(주말 아이디어, 얼마나 가까운 사람인지에 따른 선물 아이디어, 모은 돈으로 할 일), 여행(가고 싶은 곳, 여행 짐 목록, 호텔 준비물, 해외 출국 체크리스트)이에요. 이미 있던 가방에는 최신 예시가 한 번, 그 가방의 주머니 안에 추가돼요.",
    faq_q_bag_examples_list: "내 가방에는 어떤 예시가 들어 있나요?",
    faq_a_nm_me1_guide: "Me – New Me 속 나의 캐릭터의 첫 번째 모습(Me1)이에요. 처음에는 참여하자마자 반짝임에 둘러싸인 빛의 포털이 열리고 Me가 날아 나와, 몇 번만 누르면 앞으로 무엇이 기다리는지 알려 준 다음 모든 질문 곁에 머물러요: 식사를 고르는 동안에는 자기 책에 함께 글을 쓰고, 팁을 누르면 다른 팁이 나와요. 마지막에는 Me가 함께 축하하고 짧은 둘러보기로 안내해요 – 둘러보기가 끝나면 함께하는 작은 순간이 하나 더 있어요. 질문이나 둘러보기 도중에 나가더라도, 다음에 Me가 반갑게 맞이하며 같은 곳에서 이어서 할지 물어봐요. 위쪽의 \"건너뛰기\"로 오프닝을 건너뛸 수 있어요.",
