    nm_m1_skip: "건너뛰기",
    nm_m1_tip_ai: "목록에 없는 음식인가요? 나중에 \"바꾸기\"에서 직접 글로 쓰면 – AI가 계산해 줘요. 이제 매일 무엇을 먹을지 함께 골라 봐요 – 물론 언제든 바꿀 수 있어요 ✨",
    nm_m1_tip_love: "어떤 음식이든 괜찮아요 – 좋아하면 메뉴에 그대로 남아요 💛",
    nm_m1_tip_rice: "제가 제일 좋아하는 건 밥이에요: 밥이 기본이고, 주변에 이것저것 조금씩 🍚",
    faq_a_shop_basics: "쇼핑 목록이 완전히 비어 있을 때 – 예를 들어 맨 처음에 – ‘시작용 기본 목록’이 나타나요: 우유, 빵, 달걀 등. 항목을 누르면 목록에 추가되고, ‘모두 추가’를 누르면 한 번에 다 추가돼요. 목록에 뭔가 들어가면 기본 목록은 사라져요.",
