    shop_win_other: "기타…",
    shop_win_to: "끝",
    room_genie_again_no: "지금은 아니요",
    room_genie_again_no_msg: "그럼 이미 세운 목표를 이룰 때예요. 다음 목표에 도착하면 – 그곳에서 무언가가 기다리고 있을 거예요 ✨",
    room_genie_again_q: "또 왔네요? ✨ 삶에서 또 바꾸고 싶은 게 있나요?",
    room_genie_again_yes: "네",
    room_genie_bye: "또 만나요",
    room_genie_rest: "숲의 정령은 지금 쉬고 있어요 – 내일 다시 와 주세요 ✨",
    faq_a_shop_holidays: "쇼핑 목록에서 선물을 누르면 내 나라(설정에서 고른 나라)의 명절과 기념일이 날짜와 함께 순서대로 나타나요. 날짜는 해마다 알아서 계산돼요. 명절을 누르면 그날 많이 사는 것들로 준비된 목록이 열려요. 모두 선택되어 있으니(이미 목록에 있는 것은 빼고) 필요 없는 것은 체크를 풀고 ‘목록에 추가’를 누르세요. 명절 2주 전에는 목록 맨 위에 작은 카드가 나타나고, ✕를 누르면 다음 명절까지 숨겨져요.",
    faq_q_shop_holidays: "‘명절에 살 것’은 어떻게 쓰나요?",
    shop_hol_add: "목록에 추가 ({n})",
    shop_hol_added: "목록에 추가했어요: {n}",
    shop_hol_btn: "명절에 살 것",
    shop_hol_items_title: "{holiday} – 뭘 살까요?",
    shop_hol_not_now: "나중에",
    faq_a_shop_delivery: "쇼핑 목록에서 트럭을 누르고, 배달에 들어 있는 것(모두 선택되어 있어요), 도착하는 날 – 오늘, 내일 또는 다른 날 – 그리고 시간대(오전, 오후, 저녁, 또는 원하는 시간을 정하는 ‘기타…’)를 고르세요. 그 항목들은 목록 맨 위의 ‘배송 중’ 카드로 옮겨지고, 카드에 날짜와 시간대가 표시돼요. 그날이 되면 나의 하루에 ‘배달이 도착했나요?’가 나타나요(카드에도 ‘도착했나요?’가 있어요). 다 도착했다면 ‘다시 사기’로 옮겨져요. 빠진 게 있으면 안 온 것을 누르세요. 바로 목록으로 돌아가요.",
    faq_a_shop_departments: "목록이 마트 코너별로 알아서 정리돼요 – 과일·채소, 빵, 유제품·달걀, 고기·생선, 식료품, 냉동식품, 음료, 과자, 청소, 개인 관리, 유아용품, 반려동물. 그래서 진열대를 순서대로 돌 수 있어요. 코너는 항목 이름으로 알아봐요. 항목이 엉뚱한 곳에 들어갔다면 그 항목을 눌러 코너를 고르거나, ‘기타…’를 골라 직접 써 보세요.",
    faq_a_shop_share_qty: "네. 각 항목 옆의 +는 하나를 더하고(×2, ×3…) −는 하나를 빼요. 쇼핑 목록 맨 위의 공유 버튼을 누르면 코너별로 깔끔하게 정리된 목록 전체를 WhatsApp, 이메일 또는 복사로 보낼 수 있어요.",
    faq_a_shop_two_buttons: "둘 다 ‘샀어요’라는 뜻이에요. ✕는 한 번만 사는 물건에 써요. 목록에서 빠지고, 실수였을 때를 위해 🗑️ 보관함에서 기다려요. ↺는 자주 사는 물건에 써요. 목록에서 빠져서 ‘다시 사기’에서 기다려요. 목록 맨 아래 휴지통 옆의 작은 ↺ 버튼으로 열 수 있고, 거기서 한 번 누르면 항목이 다시 목록에 들어가요. 그 안의 ‘수정’에서 항목을 뺄 수 있어요. 항목을 추가할 때는 전에 샀던 것이 추천으로 나타나고, 이미 목록에 있으면 줄이 하나 더 생기지 않고 ×2가 돼요.",
