    faq_a_weekly_table: "캘린더 보기에서 월간 개요 옆에 주간 표가 있어요 – 처음에는 접혀 있고, 제목을 누르면 열려요. 한 주의 하루하루를 일정과 할 일, 반복되는 주간 작업과 함께 시간순으로 보여 줘요. ‹ ›로 주를 넘기고, 항목을 누르면 편집할 수 있게 열려요.",
