    nm_demo_title: "식사 바꾸기는 이렇게 해요",
    faq_a_new_me_challenge_journal: "챌린지가 끝나면 – 빅 챌린지, 미니 챌린지, 이번 주 챌린지 모두 – 축하 화면에 📝 어땠나요? 버튼이 있어요. 누르면 챌린지 일기에 한 페이지가 열려요: 어떤 기분이었는지(얼굴 다섯 개), 무엇이 도움이 됐는지, 무엇이 힘들었는지, 앞으로 무엇을 가져갈지 – 모두 필수는 아니고, 나중에 해도 돼요. 일기는 마법 가방 안의 다이아몬드예요: 마친 챌린지가 날짜와 쓴 내용과 함께 최신 순으로 모여 있어요 – 하나를 누르면 읽고, 고치고, 공유할 수 있어요(페이지에 있는 내용만 공유돼요). 마친 챌린지는 업적의 “내가 마친 챌린지”에서 메달도 받아요. 챌린지 일기는 일반 일기장과 따로예요.",
    faq_q_new_me_challenge_journal: "챌린지 일기는 무엇인가요?",
