    nm_chj_write: "어땠는지 쓰기",
    nm_swap_time: "시간",
    faq_a_ai_reminder_in_text: "네. 작업과 함께 적으면 돼요. 예: “내일 17:00에 택배 찾기, 1시간 전에 알림”. 알림은 작업 자체에 저장돼요. 1시간 전, 30분 전, 하루 전 등으로 정할 수 있고, 시간 없이 “알려 줘”라고 쓰면 10분 전이에요. 텍스트에 쓴 알림이 같은 창의 알림 칸보다 우선해요.",
    faq_q_ai_reminder_in_text: "같은 요청에서 AI 어시스턴트에게 알림도 부탁할 수 있나요?",
    myday_meals_all_done: "오늘 식사를 모두 체크했어요 🍽️",
    nm_tour_week_text: "일주일의 작은 챌린지. 매일 ✓ – 마지막엔 열쇠.",
    books_home_chip: "{title} · {page}쪽",
