    books_home_off_toast: "책이 홈 화면에서 내려갔어요",
    books_home_on_toast: "책이 홈 화면에 올라갔어요 📖",
    books_home_pin: "홈 화면에",
    books_home_q: "지금 몇 쪽이에요?",
    books_home_save: "저장",
    faq_a_books_home_chip: "네. 독서 코너에서 읽고 있는 책의 카드에 있는 📌 홈 화면에 버튼을 눌러요. 홈 화면 인사말 아래에 책과 페이지가 적힌 작은 버튼이 나타나요. 버튼을 누르고 새 페이지 번호를 입력해 저장하면 진행 상황이 기록돼요(독서 코너에도 반영돼요). 📌 를 다시 누르면 내려가요. 여러 권을 함께 올려 둘 수 있고 – 책마다 버튼 하나씩 – 모든 기기에서 똑같이 보여요.",
    faq_a_new_me_week_challenge: "직접 고르는 일주일짜리 작은 챌린지예요. 복도에 큰 카드가 있어요: “이번 주에는 무엇을 해 보고 싶나요?” – 카드를 누르고, 영역(나 자신과, 다른 사람과, 배우고 성장하기, 마음의 평온, 작은 용기, 집과 루틴)과 챌린지를 고른 다음 시작 시점을 정해요. 같은 챌린지는 챌린지 화면의 🌱 자기 성장에도 있어요. 날마다 카드에 ✓ 를 표시하고(일주일에 하루는 쉬어도 돼요), 한 주가 끝날 때마다 비밀 세계로 가는 새 열쇠가 생겨요. “하루에 2페이지 읽기”는 독서 코너에 기록한 페이지로 저절로 체크돼요. 한 주가 끝나면 📌 매일 할 일로 남기기를 눌러 정한 시간에 내 루틴에 추가할 수 있고, 매일 ✓ 를 할 수 있어요. 이번 주 챌린지는 한 번에 하나만 진행돼요. 빅 챌린지와 미니 챌린지는 그와 함께 계속 이어져요.",
    faq_a_room_genie: "바다가 보이는 현관 베란다에서 알라딘의 램프를 누르면 숲의 정령이 나타나고, 대화가 시작돼요. 소원이 무엇인지(삶에서 무엇을 바꾸고 싶은지), 이뤄지면 기분이 어떨지, 가는 길에 무엇이 어려운지, 지금의 상황을 어떻게 좋은 쪽으로 바꿀 수 있는지를 물어요. 그다음에는 대략 얼마나 걸릴지, 작은 첫 단계 하나와 두 단계를 더, 그리고 힘들 때를 위한 “만약… 그러면…”을 적어요. 마지막에는 소원이 단계별로 한눈에 나타나고, 내 목표에 목표로 추가하거나(단계는 목표의 길 위에 차례로 놓이고, 고른 기간에 맞춘 날짜가 붙어요. 거기서 모두 바꿀 수 있어요) 일기장에 저장할 수 있어요. 그러면 정령이 작별 인사를 해요. 둘 중 하나를 고르지 않으면 아무것도 저장되지 않아요. 두 번째 방문부터는 정령이 먼저 삶에서 또 바꾸고 싶은 게 있는지 물어요. “네”를 고르면 같은 대화가 이어지고, “지금은 아니요”를 고르면 이미 세운 목표를 이루자는 메시지가 나와요. 정령은 하루에 한 번 나와요. 소원을 저장하면(또는 “지금은 아니요”를 고르면) 내일까지 쉬어요. 질문은 소원을 계획으로 바꾸는 잘 알려진 방법을 따라요: 소원, 결과, 장애물, 계획.",
