    room_genie_to_goal: "✨ 내 목표에 목표로 추가하기",
    room_genie_turn_ex: "예를 들어 집에서 지내는 게 힘들지만 – 밖에 나가도 힘들 거예요. 그렇다면 지금 집이 주는 것 중 활용할 수 있는 건 무엇일까요?",
    room_genie_turn_q: "때로는 어려운 점이 기회이기도 해요. 지금의 상황을 어떻게 좋은 쪽으로 바꿀 수 있을까요?",
    room_sign_text: "나를 돌보기",
    room_game_tag: "가는 길에 – 잠시 멈추고 즐기기",
    room_drawer_aria: "작은 수납장",
    nm_me_choose: "선택",
    nm_me_on_screen: "화면에",
    faq_a_new_me_game: "New Me에서 게임 버튼은 늘 같은 자리에 있어요 – 복도에서도, 비밀의 방에서도, 숲 어디에서도요. 가운데 그림만 바뀌어요. 위쪽에는 여정 일차, 열쇠, 연속 기록, 오늘의 에너지(플랜 중 얼마나 먹었는지)가 있고, 그 아래에는 다음 미션 – 시간에 맞춘 다음 식사(누르면 열리고, ✓ 먹었어요가 있어요)가 있어요. 옆쪽에는 하루 전체, 챌린지, 나의 여정이 있고, 그 옆에 이번 주 챌린지가 있어요 – 7일과 오늘의 ✓. 아래쪽에는 마법 가방(New Me의 모든 것 – 세계 지도, 나의 여정, 쇼핑 목록, 업적, 챌린지 일기, 신체 치수, 변화 사진, 월간 캘린더, 하루 표, 알림, 식단 PDF, 설정. 별도의 화면으로 열려요)이 있어요. 가방의 첫 번째 항목인 세계 지도는 숲의 모든 장소를 보여 줘요 – 장소를 누르면 그곳으로 가요. 잠긴 장소에는 열쇠가 몇 개 필요한지 보여요. Me는 숲속 오솔길 위의 나의 캐릭터예요: Me1로 시작해서 챌린지를 몇 개 마치면(열쇠 4개) Me2로, 끝 무렵(열쇠 9개)에는 Me3로 자라요 – 변신하는 모습을 직접 볼 수 있어요. Me를 누르면 모든 단계가 보여요 – 이미 도달한 캐릭터는 다시 선택할 수 있어서 이전 캐릭터가 돌아올 수 있어요. Me는 둥둥 떠 있어요. 손가락이나 마우스로 끌면 닿은 입구가 열려요(잠긴 입구에는 부족한 열쇠 수가 표시돼요). Me는 모든 방과 장소에도 따라오고, 놓아 둔 곳에서 둥둥 떠 있어요. 어디로든 끌어 옮길 수 있고, 발밑의 빛나는 고리를 끌면 한 바퀴 빙 돌릴 수 있어요. Me는 움직이는 방향을 바라봐요(컴퓨터에서는 화살표로 움직이고, Q와 E로 돌려요). 복도에서는 상단 바 아래의 작은 🏠가 홈 화면으로 돌아가고, 모든 방과 장소에서는 같은 모서리의 버튼이 복도로 돌아가요.",
    faq_q_new_me_game: "게임 버튼, 세계 지도, Me는 어떻게 작동하나요?",
