    faq_a_new_me_menu_build: "먼저 설문에서 어떤 식사를 언제 하는지(식사 2번 + 간식, 식사 2번 + 가벼운 저녁, 또는 둘 다), 저녁에 뭔가 있는지 – 먹을 건지 마실 건지, 무엇을, 몇 시에 – 물어봐요. “식사 2번 + 간식”이면 식사는 점심 식사(11:30)와 저녁 식사(19:00)이고, 간식은 16:00이에요. 그다음 그 식사들의 옵션이 모두 나와요. 식사마다 좋아하는 것을 최대 2개 고르면 메뉴에 “이것 또는 저것”으로 표시돼요. 일부 옵션(피타와 스프레드, 콘플레이크와 우유, 가볍게 먹을 것)은 좋아하는 것을 최대 3개 고를 수 있어요. 각각 정해진 양이 있고, 메뉴에 “이것 또는 저것 또는 저것”으로 표시되며 칼로리는 고른 것에 맞춰져요. 커피와 음료도 같은 방식이에요. 모든 선택은 균형이 맞춰져서 하루 합계가 정확히 1,300 또는 1,500이 돼요. 언제든 바꾸려면: ⚙️ 설정 → 🍽️ 식단 구성하기, 또는 식사 카드의 “좋아하는 것 최대 3개 고르기”.",
