    nm_picks_label: "좋아하는 것 최대 3개 고르기",
    faq_a_myday_water_toggle: "네. ‘나의 하루’의 물컵(+로 한 잔 더)은 기본으로 표시돼요. 숨기려면 설정 > 개인 설정 및 캘린더에서 “‘나의 하루’에 물 표시”를 끄세요. 아무것도 삭제되지 않아요. 수분 섭취 기록은 계속 작동하고, 다시 켜면 물컵이 돌아와요.",
    faq_q_myday_water_toggle: "‘나의 하루’의 물을 숨길 수 있나요?",
    myday_water_toggle_label: "‘나의 하루’에 물 표시",
    faq_a_routine_newme_sync: "New Me가 있으면 내 루틴의 ⚙️에 ‘New Me와 동기화’ 스위치가 있어요. 켜져 있으면(기본값) 오늘의 New Me 식사가 나의 하루와 내 루틴에 나와요 – 숨긴 루틴 식사 자리에요. 끄면 New Me 식사가 두 곳 모두에서 빠지고 루틴은 원래 모습 그대로 돌아와요. 아무것도 삭제되지 않아요 – 다시 켜면 모두 돌아오고, 루틴에서 어떤 식사를 숨길지 물어봐요.",
    faq_q_routine_newme_sync: "New Me와 내 루틴, 나의 하루의 동기화는 어떻게 켜고 끄나요?",
