    theme_name_sunset_coral: "선셋 코랄",
    theme_name_watercolor_wash: "수채화",
    faq_a_food_list_languages: "기본 음식 목록은 이스라엘 음식과 히브리어 이름으로 시작했어요. 히브리어가 아닌 언어에서는 각 음식이 영어 이름으로 표시되고, 검색은 알고 있는 모든 영어 이름으로 찾아 줘요(예: 'broth'로 Clear soup를 찾음). 히브리어 이름만 있는 음식은 나오지 않아요. 목록에 없는 음식은 그냥 자신의 말로 적으면 돼요 – AI 추정은 모든 언어에서 작동해요.",
    faq_q_food_list_languages: "내 언어에서는 왜 음식 목록이 영어 이름으로 나오고, 음식 수도 적나요?",
    settings_copyright_line: "© 2026 모든 권리 보유. 앱 개발: eden zabari",
    workout_ready_replace_btn: "바꾸기",
    faq_a_sport_workout_ai: "\"나의 운동\" → ⋯ → \"AI로 플랜\"(표가 비어 있을 때는 추천 플랜 옆 타일에서도). 일주일에 몇 번, 언제, 장소, 수준, 목표를 몇 번 눌러 답하고(대부분 \"기타\"도 있어요), 원하면 \"무릎이 약해요\", \"여름까지 5km 달리기\" 같은 한 줄을 더할 수 있어요. AI가 한 주 전체를 만들어요: 운동 종류, 요일, 시간, 운동 시간, 강도, 동작, 쉬는 날. 저장하기 전에 미리 보기가 나와서 \"내 표에 넣기\"(지금 표 대신 또는 추가), \"다른 제안\"(최대 3번), \"답 바꾸기\" 중에서 고를 수 있어요. 플랜은 일부러 무리하지 않게 짜이고, 통증이나 부상을 적으면 순한 운동과 함께 전문가와 상담하라는 한 줄이 붙어요. 일정·루틴 AI와 같은 횟수를 써요: 무료 5번, 프리미엄은 한 달 60번.",
    faq_q_sport_workout_ai: "AI로 운동 플랜은 어떻게 만들어요?",
