    workout_ai_level_label: "수준",
    workout_ai_note_ph: "알아 두면 좋은 점이 있나요? 예: 무릎이 약해요, 여름까지 5km 달리기",
    workout_ai_other: "기타",
    workout_ai_replace: "지금 표 대신",
    workout_ai_title: "AI 운동 플랜",
