    workout_ai_when_morning: "아침",
    workout_ai_when_noon: "점심",
    workout_ai_when_ph: "예: 퇴근 후, 또는 17:30",
    workout_ai_working: "플랜을 만드는 중…",
    faq_a_sport_workout_jar: "운동 종류마다 색깔이 다른 별이 있어요. 달리기는 분홍, 걷기는 초록, 수영은 파랑 같은 식이에요. 이번 주에 기록한 운동은 표에서든 따로든 그 별이 \"나의 운동\" 위쪽의 유리병에 들어가고, 유리병은 주간 목표까지 차올라요(눌러서 목표를 바꿀 수 있어요). 목표에 닿으면 유리병이 반짝여요. 옆의 작은 유리병은 몇 주 연속으로 가득 채웠는지 세어 줘요.",
    faq_q_sport_workout_jar: "\"나의 운동\"의 알록달록한 별과 유리병은 뭐예요?",
    faq_a_sport_workout_gcal: "네. ⋯ → Google 캘린더에서요(설정에서 Google 캘린더를 연결한 뒤). 시간이 있는 운동은 그 요일마다 매주 반복되는 일정이 되고, 앱에서 바꾸면 함께 바뀌어요. 알림은 앱에서만 오기 때문에 Google은 따로 알림을 넣지 않고, 운동이 앱에 두 번 보이지도 않아요. 다시 누르면 Google 캘린더에서 운동만 지워져요.",
    faq_q_sport_workout_gcal: "운동이 Google 캘린더에 보이게 할 수 있나요?",
    workout_gcal_btn: "Google 캘린더",
    workout_gcal_error: "Google 캘린더를 업데이트하지 못했어요. 다음에 바꿀 때 다시 시도할게요",
    workout_gcal_not_connected: "먼저 설정에서 Google 캘린더를 연결해 주세요",
    workout_gcal_off_toast: "운동을 Google 캘린더에서 지웠어요",
    workout_gcal_on_toast: "운동이 Google 캘린더에 들어갔어요",
    faq_a_sport_workout_reminder: "네. 운동의 알림에서 10분 전, 30분 전, 1시간 전 또는 원하는 시간을 고르세요(운동에 시간이 있어야 해요). 다른 알림과 같은 소리로, 한 번 한 곳에만 울려요. 앱이 열려 있으면 앱에서, 아니면 휴대폰으로요. \"완료\"를 누르면 운동이 기록되고, \"아직\"을 누르면 5분 뒤에 다시 알려 줘요.",
    faq_q_sport_workout_reminder: "운동 전에 알림을 받을 수 있나요?",
    workout_reminder_30min: "30분 전",
    workout_reminder_label: "알림",
    workout_reminder_need_time: "알림을 받으려면 시간을 정해 주세요",
    faq_a_sport_workout_share: "⋯ → 공유에서 한 주가 테마 색의 유리 느낌 이미지로 바뀌고, 앱으로 가는 은은한 링크가 붙어요(휴대폰에서는 바로 공유 메뉴로, 컴퓨터에서는 이미지가 저장돼요). ⋯ → 인쇄용 PDF는 한 주 전체를 깔끔한 페이지로 열어 주고, 운동과 동작마다 체크할 칸이 있어요. \"PDF로 저장\"을 고르거나 인쇄하세요. 플랜은 설정의 데이터 리포트 운동 항목에도 나와요.",
    faq_q_sport_workout_share: "한 주의 운동을 공유하거나 인쇄하려면?",
    share_image_saved: "이미지가 저장됐어요. 첨부해서 보낼 수 있어요",
    share_save_image: "이미지 저장",
    workout_pdf_btn: "인쇄용 PDF",
    workout_share_btn: "공유",
    faq_a_sport_workout_board: "⋯ → 주간 보드에서는 요일마다 열이 있어요. 운동을 다른 요일로 끌어다 놓으세요(휴대폰에서는 먼저 길게 누르기). 운동에서 \"내 루틴에도 넣기\"를 켜면 그 시간과 요일에 루틴에 들어가고, 바꾼 내용은 양쪽에서 함께 맞춰져요. 내 루틴의 항목에서는 \"나의 운동에 추가\"로 반대로 할 수 있어요. 어느 쪽에서 ✓해도 양쪽에 반영되고, 나의 하루에는 물 옆의 칩에 한 번만 보여요.",
    faq_q_sport_workout_board: "운동을 다른 요일로 옮기고 내 루틴과 연결하려면?",
    routine_in_workouts_btn: "나의 운동에서 열기",
    routine_to_workout_btn: "나의 운동에 추가",
    routine_to_workout_done: "나의 운동에 추가됐어요 💪",
    workout_delete_confirm_routine: "플랜과 내 루틴에서 사라져요. 기록에 이미 남은 운동은 그대로 있어요.",
    workout_moved: "{day}으로 옮겼어요",
    workout_routine_need_time: "내 루틴에 넣으려면 시간을 정해 주세요",
    workout_routine_toggle: "내 루틴에도 넣기",
    workout_view_board: "주간 보드",
    workout_view_timeline: "타임라인",
    faq_a_sport_workout_plan: "운동 기록의 \"나의 운동\"에서 + 운동 – 종류, 요일, 시간, 운동 시간, 강도, 장소(\"기타\"도 가능)를 정해요. 근력·기능성 운동·수영에는 동작 목록을 넣을 수 있고, '휴식'은 쉬는 날을 표시해요. 추천 플랜으로 시작할 수도 있어요. 오늘의 운동은 크게, 그 아래에 한 주 전체가 보여요. ✓를 누르면 강도와 함께 운동 기록에 남아요. ⋯에서 주간 목표(횟수 또는 분)를 정할 수 있어요. 운동을 할 때마다 그 별이 유리병에 쏙 들어가요.",
    faq_a_sport_workout_today: "나의 하루에서 물 옆의 작은 칩에 오늘의 운동이 보여요. 누르면 상세 정보와 ✓, ▶가 열려요. ▶는 타이머를 시작하고, 타이머는 홈 화면의 칩에서도 계속 돌아가요. \"끝내기\"를 누르면 실제 시간으로 기록돼요. New Me에서 \"움직이는 2주\" 챌린지가 진행 중이면 기록한 운동이 자동으로 반영돼요.",
    faq_q_sport_workout_plan: "한 주의 운동은 어떻게 계획하나요?",
