    dictation_no_mic: "마이크를 찾지 못했어요. 컴퓨터에는 연결된 마이크나 마이크가 달린 헤드셋이 필요해요",
    dictation_no_speech: "말소리가 들리지 않았어요. 마이크에 조금 더 가까이에서 다시 해 보세요",
    dictation_service_off: "이 브라우저나 컴퓨터에서 받아쓰기가 꺼져 있어요. 컴퓨터 설정에서 켜거나 Chrome을 써 보세요",
    faq_a_new_me_magic_themes: "New Me에 포함된 반짝이는 테마 다섯 가지예요: 마법의 숲, 별가루, 장미 요정, 마법의 오로라, 황금빛 노을. New Me 안(⚙️ 설정 > 색상)이나 설정 > 외관 및 화면에서 하나를 고르면, 반짝이는 붓이 화면을 그 테마로 칠해요. 마법 테마에서는 앱 전체와 탭할 때마다 반짝임이 퍼져요. 언제든 다른 테마로 돌아갈 수 있어요.",
