    quotes_look_title: "문장 모양",
    quotes_look_wall: "벽",
    theme_magic_section_label: "New Me 마법 테마",
    apptour_focus_text: "지금 할 한 가지만 남고 나머지는 모두 비켜요. 큰 ✓와 함께요. 그다음 할 일이 나타나요.",
    apptour_m_presets_text: "저장한 식사를 한곳에: 검색, 최근 사용, 시간대별 – ＋로 오늘에 추가해요.",
    apptour_night_text: "🌙는 앱 전체를 어둡게, ☀️는 낮으로 되돌려요.",
    apptour_noteline_text: "쓰고 ➤를 누르면 메모에 저장돼요. 맨 앞의 📝를 누르면 🛒 장보기나 🍎 저장한 식사로 바뀌어요.",
    apptour_search_text: "메모, 장보기, 캘린더, 레시피, 노트, 목표, 표, 책까지 – 검색 한 번이면 다 찾아요.",
    faq_a_new_me_ai_menu: "메뉴 전에 설문에서 어떤 식사를 언제 하는지(식사 2번 + 간식, 식사 2번 + 가벼운 저녁, 또는 둘 다), 저녁에 작은 걸 먹는지와 몇 시인지, 먹지 않는 것, 커피나 차를 어떻게 마시는지 물어봐요. 그다음 AI가 식사마다 3가지 옵션을 만들어요. 각 옵션은 하루 중 그 식사의 몫에 맞춘 양이라 하루 합계는 여전히 정확히 1,300 또는 1,500이에요. 음료 아이디어도 만들어 고정 음료로 저장해요. 식사마다 최대 2개의 즐겨찾기를 고르고, 원래 메뉴 옵션은 바로 아래에 있으며 🔄 바꾸기에서는 나만의 메뉴 다음에 나와요. 🔄 다른 옵션은 새 세트를 만들어요(설문 1회당 3번). 답을 바꾸거나 언제든 새 메뉴를 만들려면: ⚙️ 설정 → ✨ 나만의 메뉴 (AI).",
    faq_q_new_me_ai_menu: "New Me의 나만의 메뉴는 어떻게 작동하나요?",
    nm_ai_menu_building: "식사와 시간에 맞춰 메뉴를 만들고 있어요…",
    nm_ai_menu_drinks: "추천 음료",
    nm_ai_menu_error: "지금은 나만의 메뉴를 만들지 못했어요. 원래 메뉴를 보여 드릴게요. 다시 시도하거나 나중에 ⚙️ 설정에서 할 수 있어요.",
    nm_ai_menu_original: "원래 메뉴에서",
