    room_back_to_shelf: "선반으로",
    faq_a_new_me_day_total: "매일 정확히 플랜대로 맞춰져요: 식사, 낮 동안 커피와 음료용 약 150kcal, 그리고 저녁에 고른 것 – 가볍게 먹을 것이나 마실 것. 저녁에는 좋아하는 것을 최대 3개 고르면(예를 들어 바나나, 요거트 또는 다크 초콜릿 2조각; 또는 허브티, 우유를 조금 넣은 차 또는 따뜻한 우유) 그 칼로리만큼 식사에서 빠져요. 모든 선택은 자동으로 균형이 맞춰져요: 더 작거나 큰 옵션, 뺀 식사, 작은 아침과 함께 오는 작은 식사, 또는 저녁 – 차이는 각 식사의 크기에 따라 더해지거나 빠지고, 각 식사 아래에 얼마인지(+ 또는 −)와 무엇을 더하거나 뺄지 적혀 있어요. 이미 체크한 식사는 기록된 그대로예요. 설문에서는 각 식사 옆에 조정이 보이고, 작은 상자에 식사, 음료, 저녁, 합계가 나와요. 그날 다른 게 먹고 싶나요? 총칼로리를 같거나 더 적게 유지하세요.",
    faq_q_new_me_day_total: "New Me의 하루는 어떻게 정확히 1,300 / 1,500이 되나요? 음료는 어디에 들어가나요?",
