    books_quotes_chip: "문장",
    faq_a_book_quotes: "비밀의 방 선반(문장)이나 독서 코너의 작은 \"💬 문장\" 칩에서요. 둘 다 같은 목록이에요. \"+ 문장\"을 탭하고 문장을 적은 뒤, 독서 코너의 책을 고르거나 \"✏️ 기타\"로 다른 제목을 입력하세요. 작가는 선택이에요. ✏️로 수정, 🗑️로 삭제해요. 문장은 넘겨 보는 책갈피예요. 위쪽 🎨로 사진이나 카드 벽으로 바꿀 수 있어요.",
    faq_a_room_wish_jar: "비밀의 방 선반에는 꿈을 담는 유리병이 있어요. 맨 위 칸의 작은 병을 탭하고(또는 선반 > 소원 병) 내 삶이 어떤 모습이길 바라는지 적어 보세요. 마음껏, 정답도 오답도 없이요. 소원은 한 장씩 쪽지로 접혀 병에 떨어져요. “쪽지 하나 꺼내기”는 무작위로 하나를 열고, 쪽지마다 따로 열 수도 있어요. 같은 소원을 두 번째로 열 때부터 목표로 만들고 작은 단계로 나눌 수 있어요. 일주일에 한 번, 소원이 적힌 쪽지 하나가 살며시 나타나요. 부담 없이, 어디로 가고 있는지 떠올리게 해 줄 뿐이에요.",
    faq_q_book_quotes: "좋아한 책 속 문장은 어디에 남기나요?",
