    room_wish_written: "{date}에 씀",
    faq_a_saved_meals_page: "저장된 식사에는 전용 페이지가 있어요: 영양 및 지표 > ⭐ 저장된 식사 (또는 메뉴의 ⭐). 위쪽 검색으로 이름이나 재료로 식사를 찾고, \"최근 사용\"에는 최근에 추가한 식사가 보이며, 탭(아침, 점심, 저녁, 수프…)으로 시간대별로 볼 수 있어요. \"+ 오늘\"을 누르면 오늘의 일일 식사 기록 다음 빈칸에 추가돼요. 식사를 탭하면 수정하거나 삭제할 수 있고, 위의 ＋로 새 식사를 추가해요.",
