    presets_tab_sweet: "단것",
    faq_a_notes_sticky_look: "메모는 유리 카드로 된 짧은 목록이에요. 메모 위쪽의 🎨로 메모 전체의 모양을 바꿀 수 있어요: 목록, 위쪽의 날짜 버튼, 메모를 쓰는 창까지 – 유리, 깔끔한 목록, 인덱스 카드, 마스킹 테이프. 끌고 있는 메모는 자기 모양과 색을 그대로 유지해요. 글자를 탭하면 열리고, 거기서 내용을 고치고 색을 바꾸고 마지막으로 쓴 날짜와 시간을 볼 수 있어요. 다 했으면 ○를 탭하고, ×를 누르면 보관함으로 옮겨져요(목록 아래 🗑️에서 되돌릴 수 있어요). ⠿를 잡고 끌면 순서를 바꾸거나 “나중에” 아래로, 또는 위쪽 날짜로 옮길 수 있어요. !를 누르면 메모가 급한 메모로 표시돼요 – 작은 “급함” 태그가 붙고 맨 위 줄 쪽으로 부드럽게 올라가요. 한 번 더 누르면 해제돼요.",
    faq_q_notes_sticky_look: "메모를 열고, 수정하고, 지우려면 어떻게 하나요?",
    note_to_archive_btn: "보관함으로 이동",
    faq_a_routine_clash: "같은 요일의 그 시간에 이미 항목이 있으면 두 가지 선택이 나와요. \"바꾸기\" – 새 항목이 그 시간에 들어가고, 원래 있던 항목을 옮길 시간을 고릅니다(기존 항목을 수정할 때는 그 항목의 원래 시간이 제안되어 둘이 그냥 자리를 바꿔요). \"둘 다\" – 둘 다 같은 시간에 위아래로 남아요. 요일이 다르면(예: 하나는 일~목, 다른 하나는 금요일) 아무것도 묻지 않아요.",
    faq_q_routine_clash: "루틴에서 이미 차 있는 시간에 항목을 넣으면 어떻게 되나요?",
    routine_clash_both: "✌️ 둘 다 – 둘 다 {time}에",
    routine_clash_move_btn: "옮기고 저장",
    routine_clash_move_to: "\"{title}\"을(를) 몇 시로 옮길까요?",
    routine_clash_replace: "🔄 바꾸기 – \"{title}\"을(를) 다른 시간으로 옮기기",
    routine_clash_title: "{time}에 이미 있어요: {title}",
    faq_a_new_me_coffee: "오늘 메뉴 아래에 짧은 요약이 있어요. 오늘 식사 전체가 몇 kcal인지, 커피와 음료에 얼마나 남았는지, 그리고 고른 커피와 음료 버튼 – 한 번 누르면 음료에 추가돼요. 버튼 아래 “좋아하는 것 최대 3개 고르기”에서(설문에서도) 무엇을 보여 줄지 골라요: 물 / 탄산수, 허브티, 다이어트 음료, 블랙 / 아메리카노(~5), 우유를 조금 넣은 차(~25), 물 베이스 커피에 우유나 식물성 우유 100ml까지(~50), 가벼운 핫초코, 따뜻한 우유 또는 일반 커피 / 라테(~120).",
    faq_q_new_me_coffee: "커피는 어디서 추가하고, 오늘 얼마나 남았는지는 어떻게 알 수 있나요?",
