    nm_late_room_line: "자기 전에 가볍게 · 오늘 약 {n}kcal 남음",
    faq_a_recipe_examples: "내 레시피 아래에 아침, 샐러드, 수프, 메인 요리, 곁들이, 간식, 디저트, 비건 요리 레시피 예시가 있어요. 각각 조리 시간, 1인분 칼로리, 1인분이 몇 그램인지 나와 있어요. 레시피를 누르면 열리고, \"내 레시피에 저장\"을 누르면 수정할 수 있는 내 사본이 만들어져요. 카테고리 칩으로 거를 수 있고, 같은 칩을 다시 누르면 전부 보여요.",
    faq_a_recipe_grams: "레시피 안에서 칼로리 옆에 \"1인분 ≈ Xg\"이라고 나와요. 내 레시피는 레시피 양식에서 \"1인분 그램\"(원하면 조리 시간도)을 입력하세요. 둘 다 선택 사항이고, 시간은 레시피의 색 띠에 표시돼요.",
