    faq_a_recipe_scan_multi: "네. \"레시피 추가\"에서 📷를 누르고 사진을 한 장 또는 여러 장(최대 6장, PDF도 가능) 고르세요. 각 사진이 짧은 목록에 나오면 무엇이 찍혔는지 전체, 재료, 만드는 법 중에서 고르고, \"➕ 사진 추가\"로 더 넣을 수 있어요. 그다음 \"✨ 레시피 스캔\"을 누르면 AI가 순서대로, 중복 없이 하나의 레시피로 합치고, 스캔 1회로 계산됩니다. AI 도우미의 📷 사진에서 고른 여러 장의 사진도 여기서 열려요.",
    faq_q_recipe_scan_multi: "재료와 만드는 법을 따로 찍은 사진이나 두 페이지처럼, 여러 장의 사진으로 레시피 하나를 스캔할 수 있나요?",
    recipe_scan_add_more: "➕ 사진 추가",
