    recipe_scan_run_btn: "✨ 레시피 스캔",
    recipe_scan_too_many: "레시피 하나에 사진은 {n}장까지",
    faq_a_note_written_at: "메모의 글자를 누르면 열립니다. 안에서 글자 아래에 마지막으로 쓴 날짜와 시간이 정확하게 나옵니다. 글자 자체를 바꿀 때만 업데이트되며, 보관과 복원, ✓ 표시, 색상, 메모 이동으로는 바뀌지 않습니다.",
    faq_q_note_written_at: "메모를 언제 썼는지 어떻게 보나요?",
    note_written_at: "마지막으로 쓴 시간: {date}",
    faq_a_new_me_month: "마법 가방 → 월간 캘린더에서요. 날마다 체크한 식사 수에 따라 색이 칠해지고, ‹ › 화살표로 달을 넘기며, 달력 아래에 그달의 하루 평균 칼로리가 나와요. 날짜를 누르면 그날 체크한 식사 수와 먹은 칼로리가 보여요.",
    faq_q_new_me_month: "New Me에서 지난달과 평균 칼로리는 어디서 보나요?",
    nm_month_avg: "이번 달 평균: 하루 {kcal}kcal · 기록한 날: {n}",
    nm_month_day_empty: "이 날은 기록이 없어요.",
    nm_month_day_line: "체크한 식사: {checks} · 칼로리: {kcal}",
    nm_extra_line_small: "이 식사에 {n}kcal 추가(가벼운 아침에서) – 예: {ideas}",
    faq_a_new_me_small_breakfast: "가벼운 아침(약 170kcal)이에요: 스펠트 피타(100kcal 이하)에 스프레드나 치즈, 그리고 채소 한 가지 – 좋아하는 것을 최대 3개 골라요. 예를 들어 초코 스프레드 1작은술, 땅콩버터 1작은술 또는 슬라이스 치즈 1장(지방 22% 이하). 양이 적어서 다른 시간에 “작은 식사 하나 더”가 함께 와요(예를 들어 1시간 반 뒤, 11:30 → 13:00 – 다른 시간도 고를 수 있어요): 피타와 스프레드 한 번 더, 단백질 요거트와 과일, 라이스 케이크와 치즈, 시리얼과 우유 또는 피타 반쪽과 달걀 – 약 200kcal까지, ✓도 따로 있어요. 그래도 남는 칼로리는 다른 식사에 나뉘고, 식사마다 얼마나 더해졌는지 보여서 하루 총량은 플랜 그대로예요. 설문에서 고르거나, 🔄로 오늘만 바꿀 수 있어요 – 예를 들어 아침이 늦을 때요.",
    faq_q_new_me_small_breakfast: "New Me 메뉴의 ‘가벼운 아침’은 뭔가요?",
