    weather_sky_storm: "뇌우",
    faq_a_ai_icon: "네 – 설정 > 외관 및 화면에서요. 기본은 부드러운 버블이고, Premium에서는 떠다니는 뇌나 로봇도 고를 수 있어요.",
    faq_a_new_me_favorites: "네. 설문에서(설정에서 다시 할 때도) 식사마다 최대 2가지를 고를 수 있어요. 첫 번째가 메뉴에 표시되고, 그 아래에 두 번째가 ‘또는’ 줄로 나와요 – 누르면 오늘만 그걸로 바뀌어요. 아침을 제때 못 먹었다면 ‘⏰ 나중에’로 오늘 나중 시간으로 옮길 수 있고, 칼로리는 바뀌지 않아요.",
    faq_a_theme_mode: "특별 테마 중 일부는 다크에서 가장 예뻐요 – 수채화, 오로라, 바비, 두 가지 반짝이 테마 – 그래서 이 중 하나를 고르면 앱이 다크 모드로, 다른 테마(로켓 포함)를 고르면 라이트 모드로 바뀌어요. 블랙과 다크 그레이는 다크로 남아요. 나중에 언제든 메뉴의 🌙나 설정의 라이트 모드로 바꿀 수 있어요.",
    faq_a_water_month: "물 기록에서요. 오늘 기록의 각 항목 옆에 추가한 시간이 표시되고, '월간 표'를 열면 한 달 전체가 나와요. 날마다 마신 리터 수가 표시되고(하루 목표를 채운 날은 ✓), 날짜를 누르면 그날의 기록이 시간과 함께 보여요.",
    faq_q_ai_icon: "AI 어시스턴트 아이콘을 바꿀 수 있나요?",
