    dev_sim_panel_title: "PM – 나만 보기",
    faq_a_new_me_weight_optional: "아니요. 설문의 현재 체중과 목표 체중 모두 선택 사항이에요. 나중에 체중을 기록하면(New Me ‘나의 여정’의 ⚖️ 체중 또는 체중 기록), 첫 기록부터 진행 상황을 계산해요.",
    faq_q_new_me_weight_optional: "New Me에서 체중을 꼭 입력해야 하나요?",
    nm_unlock_desc: "메뉴, 챌린지, 여정이 모두 준비됐어요. 한 걸음씩, 함께.",
    nm_unlock_title: "New Me가 열렸어요!",
    room_reveal_star: "옥상 망원경에 새 별이 반짝여요 ✨",
    faq_a_room_records: "레코드플레이어는 처음부터 방 안, 안락의자 옆 나무 그루터기 위에 있어요. 레코드를 고르면 최근 몇 년의 큰 히트곡 공식 뮤직비디오가 유튜브에서 열리고, 그 아래에는 이 방에서 바로 흐르는 잔잔한 멜로디 다섯 곡이 있어요. 흐르는 동안 레코드가 돌고, “⏹ 멈추기”를 누르면 음악이 멈춰요.",
    faq_a_room_roof_gifts: "8번째 열쇠와 함께 나타나요. 망원경을 탭하면 안을 들여다볼 수 있어요. 밤하늘이 가까이 펼쳐지고, 드래그(또는 화살표)로 둘러볼 수 있어요. 마친 챌린지들은 그 안에서 별자리를 그리고, 챌린지마다 별이 하나씩 있어요. 별을 탭하면 어떤 챌린지였는지 보여요. 작은 보물 상자를 탭하면 열려요(지금은 비어 있어요). 한 번 더 탭하면 닫혀요.",
    faq_q_room_records: "비밀의 방 레코드플레이어에는 무엇이 있나요?",
    faq_q_room_roof_gifts: "옥상의 망원경과 보물 상자는 무엇인가요?",
    room_chest_letter: "나에게 온 작은 편지",
    room_chest_letter_1: "이 길의 작은 걸음 하나하나가 진짜였어요. 그 모든 걸음이 소중해요.",
    room_chest_letter_2: "자신에게 다정한 것도 길의 일부예요. 쉬는 게 아니에요.",
    room_chest_letter_3: "가벼운 날도, 무거운 날도 있어요. 두 날 모두 함께하는 것이 진짜 힘이에요.",
    room_chest_letter_4: "쉬어도 괜찮아요. 쉬는 것도 앞으로 나아가는 거예요.",
    room_chest_letter_5: "오래 가는 변화는 조용한 변화예요. 하루하루 쌓여 가요.",
