    dev_sim_locked_toast: "🔒 잠김 – 구매 전에는 이렇게 보여요",
    faq_a_new_me_preview: "네. New Me 페이지는 안에서 일어나는 일을 보여 주는 짧은 영상으로 시작해요: 설문, 복도의 램프, 마법 가방, 챌린지와 열쇠. 그 아래에 포함된 모든 것, 하루 미리 보기, 짧은 답변이 있어요.",
