    ai_chat_food_invalid: "칼로리는 0보다 큰 숫자여야 해요",
    ai_chat_food_updated: "수정됨:",
    faq_a_ai_chat_food_fix: "네. 채팅의 답변 아래에서 ✏️ 칼로리 / 단백질 고치기를 탭하고 숫자를 바꾼 뒤 저장하세요. 방금 추가된 부분만 바뀌어요 – 이미 있던 간식에 합쳐졌더라도요. AI는 실수할 수 있으니 한 번 확인해 보세요.",
    faq_a_new_me_home_btn: "New Me가 있다면 홈 화면 위쪽 집중 모드 옆의 작은 💎이 오늘의 메뉴를 열어요. 오늘의 식사는 나의 하루에도 각각 ✓와 함께 나와요.",
    faq_a_routine_item_days: "네. 내 루틴에서 항목을 탭하고 📅 요일에서 요일을 고르세요 – 예를 들어 월요일부터 금요일까지만. 다른 날에는 나의 하루에 나오지 않고 ✓도 없어요. 내 루틴에서는 흐리게 남아 있고 옆에 요일이 표시돼요. ✓ 없이 3일이 지나면 항목에 대해 묻는 카드도 그 항목의 요일만 세요.",
