    faq_a_home_note_line: "홈 화면 가운데 줄에 쓰고 ➤(또는 Enter)를 누르면 메모에 저장돼요. 줄 맨 앞의 📝를 누르면 🛒로 바뀌고, 그때 쓴 내용은 쇼핑 목록에 들어가요. 한 번 더 누르면 🍎: 몇 글자 입력하면 맞는 저장한 식사가 나타나고, 누르면 오늘 식사에 기록돼요. 🎤로 소리 내어 말해도 돼요.",
    faq_a_night_mode: "메뉴 ☰를 열고 위쪽의 🌙를 누르면 앱 전체가 어두워져요. 같은 자리의 ☀️로 다시 낮으로 돌아와요. 설정의 '라이트 모드'에서도 바꿀 수 있어요.",
    faq_q_home_note_line: "홈 화면에서 빠른 메모는 어떻게 쓰나요?",
    faq_q_night_mode: "야간 모드로 바꾸려면 어떻게 하나요?",
    menu_day_mode: "주간 모드",
    menu_night_mode: "야간 모드",
    faq_a_secret_room_yoga: "숲속 오솔길 끝에 빛나는 문이 있고, 그 뒤 폭포 옆에는 숲속 동물 루미, 퍼피, 닉시, 스파클렛이 반원을 이루며 매트 위에 앉아 있어요. 요가 선생님 플로라는 그들을 마주 보고 바위 위에 하나만 놓인 매트에 앉아 있어요. 플로라를 탭하면 플로라가 눈을 뜨고, 모든 것이 가까이 다가오면서 대화가 천천히, 읽을 시간을 두고 시작돼요 – 플로라가 모두의 안부를 묻고, 동물들은 저마다 자기 이름으로 대답해요(줄마다 옆에 말하는 이의 작은 그림이 있어요). 그런 다음 플로라는 가까운 사람들과 함께할 때 어떤 마음인지 물어요. 대화는 답에 따라 이어져요 – 좋은 사람들, 어려운 사람, 또는 조금 외로운 마음. 어느 길이든 작은 미션(바로 ‘나의 하루’에 추가할 수 있어요. 무언가를 쓰는 미션이라면 쓸 자리가 있고, 쓴 내용은 마법 일기장에 저장돼요)과 함께 세 번 숨쉬는 자세로 끝나요. ↩은 한 걸음 뒤로, ✦은 새 대화를 시작해요. 다음 열쇠는 폭포를 열어요: 바위에 앉으면 모든 것이 사라지고 물소리만 남아요. 연못을 들여다보면 물속에서 질문이 떠올라요 – 진짜 나라면 오늘 무엇을 할까요? – 그리고 답은 ‘나의 하루’의 작은 할 일이 돼요. 따뜻한 순간이지만, 전문가와의 상담을 대신하지는 않아요.",
