    yg_g_old: "이미 당신을 아는 사람은 따뜻한 곳이에요. 짧은 메시지면 충분해요.",
    yg_g_start: "이제 당신 차례예요 🌿 요즘 가까운 사람들과 함께할 때 어떤 마음인가요?",
