    nm_time_hour: "시",
    nm_time_minutes: "분",
    routine_time_taken: "이 시간에는 이미 일정이 있어요: {title}",
    faq_a_new_me_times: "처음 설문에서, 그리고 언제든 New Me 설정 → “식사 시간”에서 정해요. 루틴에 이미 식사 시간이 있으면 거기서 가져오고 – 루틴의 식사를 숨기고 그 자리에 New Me 식사를 보여 줄 수도 있어요. 없으면 하루에 몇 끼(식사 2번 + 간식 / 식사 2번 + 가벼운 저녁 / 식사 2번 + 간식 + 가벼운 저녁)를 언제 먹을지 골라요. “식사 2번 + 간식”이면 점심 식사 11:30, 간식 16:00, 저녁 식사 19:00이에요(모두 바꿀 수 있어요). 이 시간이 복도, “나의 하루”, “내 루틴”, 알림 어디서나 식사 시간이 돼요. 무엇을 골라도 하루 칼로리는 그대로예요. 뺀 만큼은 나머지 식사에 나눠 들어가요.",
    faq_q_new_me_times: "New Me에서 식사 시간은 어떻게 정하나요?",
