    faq_a_secret_room_diary: "나만 볼 수 있어요. 일기장 페이지는 계정에 저장되어 모든 기기에서 볼 수 있고, 다른 사람은 볼 수 없어요. 비밀의 방 책상 위의 마법 일기장으로 열 수 있고, 음악 코너의 일기장으로도 열 수 있어요. 새 페이지 아래에는 접힌 월간 달력이 있어요: 페이지가 있는 날에는 점이 찍히고, 날짜를 누르면 그날의 페이지가 열려요. 거기서 페이지를 지울 수도 있어요. 일기장이 열린 뒤에는 메인 메뉴에 추가할 수도 있어요 – 일기장 안이나 New Me 설정의 스위치로요.",
    faq_a_secret_room_places: "숲의 문에 있는 입구는 저마다 자기 열쇠로 열려요. 그 뒤에는: 바다가 보이는 현관 베란다(작은 탁자 위의 알라딘 램프 – 누르면 마법 안개 속에서 숲의 정령이 솟아올라 빙글빙글 돌며 소원에 대한 대화를 시작해요 – “램프의 정령은 무엇을 하나요?”를 참고하세요), 기타와 일기장(기타는 짧고 잔잔한 멜로디를 들려주고 저절로 멈춰요. 나무에 걸린 레코드 세 장은 저마다 마법 같은 멜로디를 들려줘요 – 한 번 더 누르면 멈춰요 – 그리고 그루터기 위 일기장에는 글을 써요), 숨 쉬는 방(해 질 녘의 고요한 호수: 물 위에 연꽃 등불이 떠 있어요. 누르고 소원을 쓰면 소원과 함께 호수 저 멀리로 떠내려가요. 마법 지팡이로 모래 위에 내려놓고 싶은 것을 쓰면 손가락으로 문지를 때까지 남아 있어요), 그리고 숲속 오솔길(밤에 열리고, 등불을 누르면 낮으로 바뀌어요. 큰 나뭇가지에는 마법 그네가 걸려 있고, 벤치에는 앉을 수 있고, 표지판을 누르면 가까이 보여요: 체크할 수 있는 작은 질문 여섯 개가 붙은 판). 잠긴 입구에는 열쇠가 몇 개 남았는지 보여요. 오솔길 끝의 빛나는 문은 폭포 옆 요가로, 그리고 그곳에서 폭포로 이어져요.",
    faq_q_secret_room_diary: "일기장은 누가 볼 수 있나요?",
