    ai_chat_working_table: "잠시만요, 표를 만들고 있어요…",
    dev_weather_preview_label: "미리보기 – 내 계정에서만:",
    faq_a_ai_chat: "말풍선을 누르면 채팅이 열려요. 할 일을 고르거나(캘린더에 넣을 것, 먹은 것, 레시피 사진, 새 표) 그냥 적기만 해도 어시스턴트가 알아서 파악해요. 캘린더는 한 번, 매주, 매일 중에서 고를 수 있어요. 답은 채팅으로 오고, 거기서 다른 일로 넘어가거나 캘린더 / 먹은 것을 열 수 있어요.",
    faq_a_new_me_hall: "New Me는 마법 숲의 문 앞에서 열려요. 그곳의 입구 하나하나가 장소예요: 거대한 나무의 둥근 문은 비밀의 방으로, 속이 빈 통나무는 바다가 보이는 현관 베란다로, 버섯 집은 기타와 일기장으로, 작은 버드나무 아치는 숨 쉬는 방으로, 큰 버드나무 아치는 숲속 오솔길로 이어지고, 사다리가 있는 꽃 아치는 별빛 옥상이 열리면 그곳으로 올라가요. 잠긴 입구에는 자물쇠가 보여요. 오솔길 위에는 나의 캐릭터 Me가 떠 있고, 주위에는 게임 버튼이 있어요: 다음 미션, 이번 주 챌린지, New Me의 모든 것이 담긴 마법 가방, 세계 지도, 그리고 도구들. 위쪽의 열쇠를 누르면 열쇠를 얻는 방법이 나와요.",
    faq_a_new_me_routine_meals: "New Me에 식사가 정해져 있고 내 루틴에도 식사가 있으면, New Me가 아무것도 두 번 보이지 않도록 루틴 식사를 숨기고 그 자리에 New Me 식사를 보여 줄지 물어봐요. 그러면 내 루틴에 New Me 식사가 제시간에 💎와 ✓와 함께 보여요. 식사 이름을 누르면 루틴 위에서 바로 다른 식사를 고르거나 시간을 바꿀 수 있는 창이 열려요. 아무것도 삭제되지 않아요: New Me의 ⚙️ 설정 → 루틴의 식사에서, 또는 내 루틴 ⚙️의 ‘New Me와 동기화’를 끄면 돌아와요. New Me가 활성 상태가 아니면 저절로 돌아와요.",
    faq_a_room_computer: "“오늘 하루 지금까지 어떻게 보내고 있어요?”로 시작하는 작은 채팅이에요. 좋음, 바쁨, 힘듦 중에서 골라 한 걸음씩 함께 나아가고, 마지막에 작은 미션 하나가 나와요(바로 나의 하루에 넣을 수도 있어요). 답은 눌러도 되고 자유롭게 적어도 돼요. 적은 내용은 가장 가까운 답과 연결돼요. “↩ 뒤로”를 누르면 한 단계 돌아가 다르게 답할 수 있고, “새 채팅”은 언제든 처음부터 다시 시작해요. 바쁘거나 힘든 날에는 같은 날 나중에 컴퓨터로 돌아올 수 있어요. “다시 왔어요...”로 대화를 이어 가요. 아래의 초록 불빛으로 컴퓨터를 끄고 켤 수 있어요. 고른 답만 저장되고, 이 기기에서만, 그날이 끝날 때까지만 남아요.",
    faq_q_ai_chat: "어시스턴트와 어떻게 대화하나요?",
    faq_q_new_me_hall: "New Me의 복도는 무엇인가요?",
