    routine_nudge_general_text: "바쁜 시기였거나, 휴가였거나, 그냥 쉬어 간 걸 수도 있어요 – 그래도 괜찮아요. 루틴을 평소처럼 이어 갈까요, 아니면 뭔가 바꿀까요?",
