    dictation_mic_denied: "마이크가 차단돼 있어요. 브라우저 주소 옆 🔒나 휴대폰 설정에서 허용해 주세요",
    faq_a_dictation: "네. 빠른 메모나 노트의 쓰기 페이지 모서리에 있는 🎤 마이크를 탭하고 말하면, 말하는 동안 앱 언어로 글이 써져요. 다시 탭하면 멈춰요. 처음에는 브라우저가 마이크 사용 권한을 물어봐요. Chrome / Android와 iPhone의 Safari에서 작동해요. 컴퓨터에서는 마이크와 Chrome, Edge, Safari 같은 브라우저가 필요해요. 뭔가 빠졌으면 메시지가 정확히 알려 줘요.",
    faq_q_dictation: "타이핑 대신 말로 할 수 있나요?",
    faq_a_secret_room: "New Me 안에 있는 나만의 방이에요 – 거대한 나무 속의 집이죠. 한 번에 벽 하나가 보이고, 화살표(또는 스와이프)로 돌아볼 수 있어요. 첫 번째 열쇠는 서로 다른 3일에 식사에 ✓ 하면 받을 수 있고, 문과 함께 방 전체가 열려요: 컴퓨터, 게임, 레코드플레이어, 서재가 들어 있는 선반, 고양이. 그다음부터는 챌린지를 하나 마칠 때마다(이번 주 챌린지도 포함) 열쇠를 받아 다음 장소가 열려요: 별빛 옥상, 바다가 보이는 현관 베란다, 기타와 일기장, 숨 쉬는 방, 요가가 있는 숲속 오솔길, 폭포, 옥상의 서프라이즈. 그리고 8번째 챌린지는 과거에서 온 편지가 든 병을 바다에서 가져와요. 무언가 열리면 화살표가 길을 알려 줘요. 게임기 아래쪽의 작은 문도 열려요 – 지금은 그 뒤의 수납장이 비어 있어요. 별빛 옥상에서는 탭한 별이 별똥별처럼 떨어지고, 고양이는 쿠션 위에 앉아 있어요.",
