    settings_weather_hint: "지금 있는 곳의 날씨에 따라 홈 화면 배경에 비, 구름, 눈이 나타나요. 대략적인 위치는 이 기기에만 저장되고, 저희 서버를 통해 MET Norway에서 확인해요.",
    settings_weather_label: "홈 화면 하늘에 날씨 표시",
    weather_failed: "지금은 날씨를 확인할 수 없어요.",
    weather_location_denied: "위치에 접근할 수 없어요. 브라우저 설정에서 허용한 뒤 다시 시도해 주세요.",
    faq_a_home_focus: "홈 화면 위쪽의 ◎를 누르면 지금의 한 가지 – 이 시간에 있는 일, 또는 오늘 목록의 다음 일 – 와 큰 ✓, 빠른 메모만 남고 모두 사라져요. ✓ 하면 다음 일이 나타나요. 위쪽의 '집중 모드 ✕'를 누르면 모두 돌아와요.",
    faq_a_home_search: "메뉴 ☰를 열면 맨 위에 검색이 있어요. 2글자 이상 입력하면 메모, 쇼핑 목록, 캘린더, 레시피, 노트(제목과 페이지 글), 목표, 테이블, 책에서 결과가 종류별로 나오고, 누르면 바로 그곳으로 이동해요.",
    faq_a_my_day: "'나의 하루'는 예전의 '오늘 살짝 엿보기'와 '내 루틴'을 하나의 타임라인으로 합친 거예요. 홈 화면 아래에서 얼마나 했는지, 지금 또는 다음에 할 일(빠른 ✓와 함께)을 볼 수 있고, 제목 옆에서 +1로 물 한 잔을 기록할 수 있어요. 누르거나 위로 밀면 하루 전체가 열려요: 위에는 시간이 없는 일, 그다음 시간 순서로 모든 것 – 캘린더의 할 일·일정·회의, 매주 고정 시간, 오늘의 루틴, 목표의 작은 걸음, New Me 식사 – 그리고 '지금' 선. 할 일, 루틴, 회의와 일정으로 걸러 볼 수 있어요. 여기의 ✓는 다른 곳(내 루틴, 내 목표, 캘린더)과 같은 ✓이고, 코너에 데이지를 피워요. '루틴 편집'은 '내 루틴'(메뉴에도 있어요)을 열고, '＋ 오늘에 추가'는 오늘 할 일을 추가해요. '나의 하루' 제목(또는 위의 작은 막대)을 누르면 다시 닫혀요.",
    faq_q_home_focus: "집중 모드가 뭔가요?",
