    faq_a_table_shopping_link: "쇼핑 목록과 연결된 ✓ 열(예: '이번 주 식단'의 '재료 있음')에서는 아직 체크하지 않은 행마다 🛒이 있어요. 한 번 누르면 쇼핑 목록에 추가돼요 – 딱 한 번만, 중복 없이요. 여기서 ✓하면 목록에서 빠지고, 목록에서 지우면 여기서도 더 이상 '목록에 있음'으로 보이지 않으며, 목록에서 구매 완료로 표시하면 여기 행에 자동으로 ✓가 돼요. 어떤 ✓ 열이든 열 설정에서 연결하거나 끊을 수 있어요.",
