    faq_a_goal_small_steps: "'내 목표'의 모든 목표는 하나의 길이에요: 이미 지나온 단계, 빛나는 오늘의 돌, 그리고 끝에 있는 트로피. 목표에 작은 걸음을 정해 보세요 – 매일, 또는 원하는 요일에 매주 – '가벼운 달리기 10분'처럼 힘든 날에도 할 수 있는 것으로요. 오늘의 작은 걸음은 모두 '내 목표' 맨 위와 '나의 하루'에 나타나고 바로 ✓할 수 있으며, 목표의 길 아래에 있는 '✓ 오늘 했어요'를 누르면 최근 7일의 점이 채워져요. '10점을 향해 · 멈추지 않아요' 메모는 일부러 맨 위에 그대로 있어요: 완벽하지 않아도 돼요 – 앞으로 나아가려면 매일 조금씩 하면 돼요.",
