    nm_plan_life: "평생 이용",
    faq_a_new_me_tour: "구매하고 짧은 설문을 마치면 바로, 짧은 투어가 게임을 보여 줘요: 상단 바, 다음 미션, 양쪽의 도구, 이번 주 챌린지, 마법 가방, 세계 지도, 나의 캐릭터 Me, 그리고 비밀의 방으로 가는 1번 문. ⚙️ 설정 > 🧭 New Me 투어 에서 언제든 다시 볼 수 있고, 설문에 적은 전체 이름도 거기서 바꿀 수 있어요. 구매 전에는 메뉴의 New Me 옆에 🔒가 보이고, 누르면 포함된 모든 내용을 담은 페이지가 열려요.",
