    nm_tour_tiles_text: "여정과 업적, 쇼핑 목록, 신체 치수, 사진, 월간 캘린더, 알림, 식단 PDF.",
    nm_tour_tiles_title: "그 밖의 모든 것",
    nm_tour_challenges_text: "20개의 챌린지 중에서 골라 원할 때 시작 – 마지막엔 선물이 기다려요.",
    nm_tour_drinks_text: "커피, 차 또는 다른 음료 – 칼로리가 자동으로 계산돼요. 탭해서 열어요.",
    nm_tour_swap_text: "🔄 식사 교체 – 식단, 저장된 식사, 또는 AI로 작성, 오늘만 또는 앞으로 계속. ⭐ 저장, ➖ 식단에서 빼기.",
    nm_tour_menu_text: "오늘의 식사. 식사를 마치면 ✓ – 일일 식사 기록에 자동으로 추가돼요.",
    nm_tour_ring_text: "링은 오늘 플랜에서 얼마나 남았는지 보여줘요. 운동하면 늘어나요.",
