    nm_sales_a3: "일반적인 식단이며 의학적 조언이 아니에요. 시작 전에 의료 면책 조항이 표시되며, 먼저 보건 전문가와 상담하는 것이 좋아요.",
    nm_sales_q3: "나에게 맞을까요?",
    nm_sales_a2: "아니요 – New Me는 별도의 프로그램이며, 프리미엄 전체가 포함되어 있어요.",
    nm_sales_q2: "프리미엄에 포함되나요?",
