    nm_cert_stat_badges: "업적",
    faq_a_new_me_advanced: "고급 모드는 20개 챌린지를 모두 마친 뒤 선물과 함께 열리고, 🎁 나를 위한 선물에서 켜고 끌 수 있어요. New Me를 금빛 화면으로 바꾸고, 자유로운 메뉴 구성 – 모든 바꾸기에서 칼로리 제한 없이 전체 옵션 표시 – 과 📊 고급 통계 화면을 제공해요: 최근 30일 칼로리와 플랜 비교, 요일별 좋은 날, 목표 도달 예상일이 포함된 체중 추세, 저녁 체크인 평균, 챌린지 기록.",
