    nm_gift_locked_view: "선물은 {n}개 챌린지를 모두 마치면 열려요 – {left}개 남았어요.",
    nm_gift_intro: "{n}개의 챌린지를 한 걸음씩. 기다리고 있던 선물이에요:",
    nm_gift_title: "나를 위한 선물",
    faq_a_new_me_letter_gift: "New Me를 시작할 때(또는 나중에 챌린지 화면에서) 미래의 나에게 편지를 쓸 수 있어요. 봉인하면 열릴 때까지 읽거나 수정할 수 없어요. 편지는 비밀의 방에 있는 바다에서 온 병 안에서, 또는 20개의 챌린지를 모두 마쳤을 때 열려요 – 그때는 선물도 기다리고 있어요.",
    faq_q_new_me_letter_gift: "과거에서 온 편지란?",
    faq_a_new_me_challenges: "🏆 챌린지에는 20개의 챌린지가 있어요: 빅 챌린지 10개(설탕 없는 5일, 탄수화물 없는 일주일, 한 달에 4 kg 감량 – 매일 칼로리 적자·운동·설탕 없이 등)와 미니 챌린지 10개 – 설탕 없는 시나몬 커피처럼 일주일 동안의 작은 습관이에요. 챌린지를 고르면 언제 시작할지 물어봐요: 오늘, 내일, 다음 주 또는 다른 날짜. 빅 챌린지와 미니 챌린지는 동시에 할 수 있어요. 진행 중인 챌린지는 메뉴 맨 위와 나의 하루에 나오고, 그날의 ✓를 할 수 있어요. 챌린지 일주일마다 챌린지를 끊지 않는 자유일(🍕)이 하루 있고, 체크하지 않은 날은 자유일로 계산돼요 – 오늘과 어제는 체크할 수 있어요. 자동으로 체크되는 날도 있어요: 운동 기록에 남긴 20분 운동, 또는 ✓를 한 메뉴 식사. 각 챌린지에는 정확히 무엇이 포함되는지 알려주는 ⓘ가 있어요(예: 탄수화물 전체 목록) – 챌린지 안과 나의 하루의 챌린지 옆에. 그 아래 🌱 자기 성장에는 일주일짜리 작은 챌린지 48개가 있어요(20개에는 포함되지 않아요) – “이번 주 챌린지가 뭐예요?”를 참고하세요.",
