    faq_a_workout_calories: "네. 운동마다 소모 칼로리 추정치가 계산돼요 – 종류, 시간, 최근 체중으로 (달리기와 자전거는 거리를 넣으면 속도까지 반영). 운동 목록과 월간 요약(소모)에 표시되고, 그날의 칼로리 예산에 더해져요: 일일 식사 기록, 칼로리 및 체중 지표, New Me의 링에서요. 추정치라서 ~와 함께 표시돼요.",
    faq_q_workout_calories: "운동이 하루 칼로리에 반영되나요?",
    faq_a_new_me_flexible_menu: "네. 설문과 설정에서 하루 식사 수를 고를 수 있어요 – 식사 2번 + 간식 / 식사 2번 + 가벼운 저녁 / 식사 2번 + 간식 + 가벼운 저녁. 식사 카드의 ➖로 식사를 뺄 수 있고(최소 3개는 남아요) ‘다시 넣기’로 되돌릴 수 있어요. 어떤 경우든 하루 칼로리는 그대로예요. 뺀 만큼은 나머지 식사에 나눠 들어가고, 각 식사 아래에 얼마나 늘었는지와 무엇을 더할 수 있는지 보여요. ✏️ 수정을 누르면 식사 내용이 열리고, 원하는 대로 바꾸면(예: 빵 없이, 달걀 하나 더) AI가 칼로리와 단백질을 다시 계산해요. 🔄 바꾸기에는 메뉴 선택지, ⭐ 저장된 식사, ✨ 직접 쓰기가 있고, 모든 변경은 오늘만 또는 지금부터 계속으로 정할 수 있어요. ‘하루 전체’ 맨 아래에는 ➕ 음식 추가가 있어요 – 메뉴 밖에서 먹은 것을 쓰면 AI가 계산해서 오늘에 더해 줘요(✕로 삭제).",
    faq_q_new_me_flexible_menu: "New Me에서 식사 횟수를 바꾸거나 내 식사를 먹을 수 있나요?",
