    share_footer_sent_from: "NOT10.ai에서 보냄",
    faq_a_goal_days_challenge: "'내 목표'에서 ＋(또는 미리 준비된 예시 '🔥 8일간')를 누르고, '📆 매일 챌린지'를 선택한 뒤 며칠인지 입력하고 매일 할 일을 추가하세요(예: '30분 걷기', '내 식단대로 먹기'). 매일 챌린지의 길 아래에서 그날의 할 일을 체크하세요 – 모두 체크하면 그날이 인정되고, 길이 돌 하나만큼 나아가며 🔥 연속 기록이 늘어납니다(매일 할 일이 없으면 '✓ 오늘 해냈어요' 버튼 하나만 있습니다). 할 일 옆의 🔁 버튼을 누르면 원하는 시간에 '내 루틴'에 추가됩니다: 그곳에서 체크하면 목표에서도 체크되고, 반대도 마찬가지입니다. 일반 목표의 단계도 같은 방법으로 '내 루틴'에 추가할 수 있습니다.",
    faq_q_goal_days_challenge: "'8일간 걷기와 건강한 식사' 같은 챌린지는 어떻게 만들고 내 루틴과 연결하나요?",
