    vision_focus_ribbon: "🎯 이달의 목표",
    vision_tagline: "큰 목표, 작은 발걸음.",
    faq_a_app_tour: "투어는 처음 들어올 때 한 번 자동으로 열려요. 먼저 투어의 부분들이 나오고, 하나를 누르면 바로 그 부분으로 이동해요. 그다음 앱의 모든 부분(홈 화면, AI 도우미, 메뉴의 모든 항목)과 설정의 다섯 그룹을 짧은 설명과 함께 보여 주고, 몇 가지는 안쪽까지 살펴봐요(예: 목표 경로 예시, 가방, Google Calendar). '계속'은 앞으로, '뒤로'는 뒤로, '이 부분 건너뛰기'는 다음 부분으로 넘어가고 ✕는 투어를 닫아요. 설정 > 도움말 및 사용법 > 앱 투어에서 언제든 다시 보고, 멈춘 곳부터 이어서 볼 수 있어요. '계속'과 '뒤로'는 항상 화면 아래 같은 자리에 있고, 컴퓨터에서는 키보드 화살표 키도 쓸 수 있어요.",
    faq_q_app_tour: "앱 투어를 다시 보려면 어떻게 하나요?",
    apptour_done_text: "궁금한 점이 있나요? 설정의 '도움말 및 FAQ'에서 모든 답을 찾을 수 있고, 이 투어는 언제든 '도움말 및 사용법'에서 다시 볼 수 있습니다.",
    apptour_done_title: "이게 전부입니다! 🎉",
    apptour_flow_recurring: "할부 및 자동이체",
    apptour_flow_weight: "체중",
    apptour_flow_calories: "오늘의 칼로리",
    apptour_flow_calendar: "캘린더",
    apptour_connect_text: "한곳에서 한 일이 다른 곳에도 자동으로 반영됩니다:",
    apptour_connect_title: "모든 것이 연결되어 있습니다",
    apptour_s_support_text: "도움말 및 FAQ, 문의하기, 앱 공유, 그리고 언제든 이 투어까지.",
    apptour_s_account_text: "프리미엄, 비밀번호, 개인 PDF 리포트, Google Calendar 동기화, 계정 삭제.",
    apptour_s_notifications_text: "리마인더 알림과 소리. 리마인더의 '⏰ 아직이요'는 스누즈처럼 작동해 5분마다 다시 알려 줍니다.",
    apptour_s_personalization_text: "국가, 하루 식사 및 간식 수, 재정 월의 시작일, 홈 화면에 표시할 항목.",
    apptour_s_appearance_text: "언어, 라이트 또는 다크 모드, 테마, 글꼴, 텍스트 색상, 접근성, 화면 크기.",
    apptour_m_style_text: "이 버튼으로 메뉴를 큰 타일로 바꾸고 다시 되돌릴 수 있습니다. 홈 화면에는 둘 중 하나만 표시됩니다.",
    apptour_m_style_title: "목록 또는 타일",
