    apptour_m_receipts_text: "세금계산서와 영수증을 사진과 함께 보관하세요. 가정용이든 사업용이든.",
    apptour_m_budget_link: "할부와 자동이체(엑셀 가져오기 포함), 나만의 카테고리, 설정의 예산 초기화 날짜.",
