    apptour_m_sport_link: "'내 루틴'의 습관이 여기에 운동을 자동으로 기록할 수 있습니다.",
    apptour_m_sport_text: "한 주의 운동 플랜과 종류·시간·거리별 운동 기록. 사진도 첨부할 수 있어요.",
    apptour_m_water_text: "하루 목표 대비 마신 물의 양을 기록합니다.",
    apptour_m_calories_link: "체중 기록도 여기에 있으며 New Me 및 '내 목표'의 체중 목표와 공유됩니다.",
    apptour_m_calories_text: "목표 대비 일간, 주간, 월간 칼로리 통계.",
    apptour_m_meals_link: "저장된 식사, 음식 목록, AI 추정. New Me, 빠른 추가, 음료도 여기에 합산됩니다.",
    apptour_m_meals_text: "매 끼니를 칼로리와 단백질로 하루하루 기록합니다.",
    apptour_m_recipes_link: "AI 어시스턴트의 📷 사진으로 적힌 레시피를 스캔하세요.",
    apptour_m_recipes_text: "카테고리별 레시피. 사진, 칼로리, 인분까지.",
    apptour_m_goal_link: "체중이나 완료한 할 일을 자동으로 추적할 수 있습니다.",
    apptour_m_goal_text: "한 달에 하나의 목표. 진행률 바와 달성 보상이 있습니다.",
    apptour_m_shopping_link: "'빠른 메모'에서 순식간에 항목을 추가하세요.",
    apptour_m_shopping_text: "쇼핑 목록. 매장에서 항목을 체크하세요.",
    apptour_m_notes_link: "메모를 '오늘', '내일' 또는 다른 날짜로 끌어다 놓으면 할 일이 됩니다. 삭제한 메모는 🗑️ 보관함에 남습니다.",
    apptour_m_notes_text: "메모와 아이디어를 하나의 목록에.",
    apptour_m_tables_link: "AI 어시스턴트가 테이블을 자동으로 설계할 수 있습니다.",
    apptour_m_tables_text: "선물, 시리즈, 목록 등 개인 테이블. 텍스트, 숫자, 선택, 날짜, ✓ 열을 쓸 수 있습니다(프리미엄).",
    apptour_m_study_link: "✅ 할 일 카드 안의 🪄 스마트 분할이 큰 일을 캘린더 속 작은 단계로 나눠 줘요.",
    apptour_m_study_text: "내 가방: 생활의 영역마다 주머니가 있고, 그 안에 노트, 테이블, 할 일이 들어 있어요.",
    apptour_m_vision_link: "단계의 📅로 캘린더에 넣을 수 있어요. 작은 걸음과 매일 챌린지의 할 일은 '나의 하루'에 나타나고, 진행 상황은 숫자나 체중으로도 볼 수 있어요.",
    apptour_m_vision_text: "목표는 작은 걸음으로 이어진 길 – 오늘의 걸음은 맨 위에. 안을 들여다볼까요 👇",
    apptour_m_myweek_link: "Google Calendar와 동기화됩니다(설정에서).",
    apptour_m_myweek_text: "월간 캘린더, 알림이 있는 반복 주간 작업, 날짜가 정해진 모든 일정. 그리고 이번 주 미팅을 적는 종이 다이어리 🤝.",
    apptour_m_newme_link: "모두 '일일 식사 기록'과 '나의 하루'에 반영되고, 체중은 '칼로리 및 체중 지표'와 공유됩니다.",
    apptour_m_newme_text: "마법의 게임 세계 속 1,300 / 1,500칼로리 식단 플랜: ✓ 표시가 있는 오늘의 식단, 세 가지 방법으로 바꾸기 – 식단에서, 저장된 식사에서, 또는 먹은 것을 AI에게 쓰면 칼로리를 계산해 줘요 – 쇼핑 목록, 식사 알림, 그리고 업적·치수·사진이 담긴 변화의 여정. 그리고 🏆 20개의 챌린지 – 마지막엔 선물도 – 그리고 이번 주 챌린지도 있어요.",
    apptour_ai_table_text: "필요한 테이블을 설명하면 AI가 열을 설계합니다(프리미엄).",
    apptour_ai_photo_link: "'내 레시피'에 저장됩니다.",
    apptour_ai_photo_text: "적힌 레시피를 찍으면 AI가 새 레시피를 채워 줍니다.",
    apptour_ai_schedule_link: "캘린더와 '나의 하루'에 표시됩니다.",
    apptour_ai_schedule_text: "계획을 평소 말투로 설명하세요. 한 번이든 반복이든 바로 캘린더에 들어갑니다.",
    apptour_ai_food_link: "바로 '일일 식사 기록'과 오늘의 합계에 반영됩니다.",
    apptour_ai_food_text: "먹은 음식을 입력하면 칼로리를 추정해 자동으로 기록합니다.",
    apptour_newme_short_text: "New Me를 엽니다. 오늘의 식단이 메인 화면에 바로 있습니다.",
    apptour_ai_link: "여기 표시되는 작은 1 배지는 매일의 '오늘 가장 중요한 일' 알림입니다.",
    apptour_ai_text: "쉬운 말로 쓰기만 하면 비서가 나머지를 해 줘요: 칼로리 기록, 계획을 캘린더에 넣기, 사진에서 레시피 읽기, 표 만들기.",
    apptour_quicknote_link: "📝와 🛒는 전체 목록을 열고, 🍎는 저장된 식사를 '일일 식사 기록'에 기록합니다.",
    apptour_quicknote_text: "빠르게 적어 두세요. '메모'에 넣거나 바로 '쇼핑 목록'에 추가할 수 있습니다.",
    apptour_routine_link: "습관이 '운동 기록'에 운동을 자동으로 남길 수 있습니다.",
    apptour_routine_text: "시간대별 하루 루틴을 탭(아이, 공부, 일…)으로 나눠 관리합니다. 매일 ✓ 표시로 습관과 연속 기록을 쌓으세요. 📅은 한 달 전체를 보여 줍니다.",
    apptour_premium_text: "AI 어시스턴트 전체 기능, 테마, 글꼴, 내 가방 등을 열어 줘요.",
    apptour_note_text: "한 주 내내 쓰는 스티커 메모입니다. 안의 ⚙ 톱니바퀴로 1–3줄 체크리스트를 추가하고 색상과 스타일을 바꿀 수 있습니다.",
    apptour_peek_link: "AI, 캘린더, 목표 단계, Google Calendar의 할 일이 모두 여기에 표시되고, 오늘의 칼로리 🔥와 🎯 이달의 목표도 보입니다.",
    apptour_peek_text: "오늘의 모든 것을 한곳에 – 할 일, 회의, 루틴, 작은 걸음이 하나의 타임라인에. 여기서 바로 ✓.",
    apptour_date_text: "탭하면 월간 캘린더를 빠르게 보고 바로 무언가를 추가할 수 있습니다.",
