    faq_a_vision_board_today: "'내 목표'에서 목표의 길 아래('계획')에 있는 단계 옆 📅를 누르고 날짜를 고르세요. '🔁 완료할 때까지 매주'를 켤 수도 있습니다 – 그러면 한 번 체크할 때까지 매주 같은 요일에 다시 나타납니다. 단계는 그날 '나의 하루'와 캘린더에 표시되고(Google Calendar가 연결되어 있으면 그곳에도), 버튼에는 언제로 일정이 잡혔는지 표시됩니다. 어느 한쪽에서 ✓를 누르면 다른 쪽에도 체크되고 목표의 길도 앞으로 나아갑니다. 날짜를 바꾸거나 캘린더에서 삭제하려면 📅를 다시 누르세요. 한 번만 하는 할 일을 캘린더에서 삭제하면 목표에서도 그 단계가 삭제되고, 매주 반복되는 알림에서 한 주만 삭제하면 그 주만 삭제됩니다.",
