    nm_drinks_hint: "음료 이름만 입력하면 칼로리가 자동으로 계산되고, 숫자는 바꿀 수 있어요.",
    nm_slot_drinks: "음료",
    faq_a_new_me_tracking: "New Me 위쪽의 다음 미션을 누른 다음 ✓ 먹었어요를 누르면 다음 식사가 먹은 것으로 표시돼요 – 끼니마다 ✓가 있는 전체 식단은 옆쪽의 ‘하루 전체’에 있고, 오늘의 식사는 홈 화면의 나의 하루에도 나타나요 – 거기서 식사를 누르면(또는 마우스를 올리면) 무엇을 먹으면 되는지 정확히 보여 주고, ✓와 ‘바꾸기’도 있어요. 모든 건 일일 식사 기록과 동기화돼요: 플랜 식사, 음료, 그리고 다른 곳에서 추가한 것(예: 빠른 추가로 넣은 커피)은 New Me와 나의 하루에서 함께 계산돼요 – 이미 입력한 건 덮어쓰지 않고, ✓를 지우면 New Me 부분만 지워져요. 오늘 식사가 모두 체크되면 작은 축하가 있어요. ‘음료’에는 하루 동안 마신 음료를 기록해요 – 모두 합쳐 ~150 kcal까지, 즉 ~50 kcal 이하 음료 3잔 정도예요. 음료 이름만 적으면 칼로리가 AI로 자동 입력돼요. 커피/차 두 줄에는 ‘우유는? 얼마나?’ 칸도 있어서(예: ‘조금’ 또는 ‘50 ml’) 계산이 업데이트돼요. 숫자는 추가 전에도 후에도 바꿀 수 있어요. 이름과 칼로리가 있는 음료는 다음으로 넘어가는 순간 자동 저장돼요 – ‘추가’를 누르는 건 선택이에요. 음료 옆의 ☆를 누르면 자주 마시는 음료로 저장돼요 – 자주 마시는 음료는 음료 카드 위쪽에 버튼으로 나타나고, 한 번 누르면 그날에 추가돼요. ⭐는 식사를 저장한 식사로 저장해요. ‘하루 표’는 먹은 것을 칼로리와 단백질과 함께 보여 줘요. 홈 화면 위쪽 집중 모드 옆의 작은 💎 버튼으로 바로 열 수 있어요. 칼로리와 단백질 값은 AI 추정치라 오류가 있을 수 있어요. 다 안 먹었나요? 체크한 식사 아래의 ‘다 안 먹었나요?’에서 양의 4분의 1, 절반 또는 4분의 3을 빼거나 – 적은 내용만큼 계산해서 빼면 – 하루 칼로리가 업데이트돼요.",
    faq_q_new_me_tracking: "New Me에서 ✓, 바꾸기, 칼로리는 어떻게 작동하나요?",
    faq_a_new_me_what: "New Me는 별도의 하루 식단 프로그램으로, 두 가지 준비된 플랜(1,300 또는 1,500kcal)이 주식 2끼와 간식 2번으로 구성되며 각각 3가지 선택지가 있어요. 프리미엄 전체가 포함돼요. 가격: 월 $11.99(언제든 해지) 또는 한 번 $99.99로 평생 이용. 메뉴의 💎 New Me에서 열 수 있어요. 시작 전에 짧은 설문이 있으며, 먼저 의료 면책 조항에 동의해야 해요. 이 프로그램은 일반 정보일 뿐이며 의사나 임상 영양사를 대신하지 않아요.",
