    daily_focus_p6_d4_s1: "목표에 도달한 사람의 내면의 평온을 유지하기", daily_focus_p6_d4_s2: "깊게 숨을 쉬며 내가 쏟은 노력의 결실을 누리기", daily_focus_p6_d4_s3: "곧 열릴 새로운 장 앞에서 나 자신을 믿기", daily_focus_p6_d4_s4: "큰 일들을 우아함과 완전한 평온함으로 마무리하기", daily_focus_p6_d4_s5: "내 안에서 발견한 회복력과 절제, 힘에 감사하기",
    daily_focus_p6_d5_s1: "높은 기준을 변함없는 삶의 방식으로 지키기", daily_focus_p6_d5_s2: "나를 기다리는 새로운 정상에 시선을 맞추기", daily_focus_p6_d5_s3: "내 성장의 다음 단계를 향해 설렘을 선택하기", daily_focus_p6_d5_s4: "무한한 능력을 느끼며 목표 달성을 축하하기", daily_focus_p6_d5_s5: "나 자신과 세상 어떤 목표든 정복할 수 있는 내 능력을 믿기",
    daily_focus_p6_d6_s1: "존중하는 마음으로 개인적인 축하와 합당한 휴식을 위한 자리를 마련하기", daily_focus_p6_d6_s2: "감사와 힘, 깊은 만족감으로 한 해 전체를 정리하기", daily_focus_p6_d6_s3: "호기심과 자신감, 이 길에 대한 사랑으로 앞을 바라보기", daily_focus_p6_d6_s4: "최선을 다했음을 알며 깊은 고요함 속에서 내려놓기", daily_focus_p6_d6_s5: "다음 순환을 위해 새롭고 상쾌한 에너지로 채워지기",
    daily_focus_p6_d7_s1: "삶을 축하하고 고요함과 깊은 감사에 하루를 온전히 바치기", daily_focus_p6_d7_s2: "온전함과 충만한 만족감 속에서 내면의 고요에 귀 기울이기", daily_focus_p6_d7_s3: "성장과 용기, 성공으로 가득했던 한 해에 대해 나 자신을 인정해주기", daily_focus_p6_d7_s4: "모든 것을 내려놓고 맑고 평온한 존재를 누리기", daily_focus_p6_d7_s5: "이 여정을 통해 내가 되어간 사람에게 감사하기",
    faq_q_daily_focus_prompt: "오늘 가장 중요한 일이 무엇인지 묻는 작은 알림은 무엇인가요?", faq_a_daily_focus_prompt: "Premium 일일 알림입니다. 하루에 한 번 AI 어시스턴트 아이콘에 작은 “1” 배지가 나타납니다. 배지를 탭하면 오늘 가장 중요한 일이 무엇인지 묻는 말풍선이 열리고, 바로 5가지 추천 항목(매일 바뀌며, 1년 동안 다양한 주제를 돌아가며 보여 주어 늘 새롭습니다)과 직접 쓸 수 있는 '기타'가 표시됩니다. 여러 개를 고를 수도 있습니다. 추가를 탭하면 고른 항목이 '나의 하루' 위쪽에 작은 알림 태그로 표시됩니다(체크하는 할 일은 아닙니다). ✕로 닫거나 바깥쪽을 탭하면 배지가 사라지지 않고 그날 남은 시간 동안 흐리게만 표시됩니다. 기본값은 켜짐이며, 설정 > 개인 설정 및 캘린더에서 끌 수 있습니다. 오늘은 아니라면 '🌙 오늘은 패스'를 누르세요. 배지는 내일까지 사라지고, 내일 평소처럼 질문이 다시 나타나요. 제안 중 하나는 나의 실제 기록에서 나와요 – 이달의 목표의 다음 단계나 오늘의 독서 등. 매일 새롭게 시작해요.",
